import json,time,statistics,sqlite3
from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from second_brain import ledger
h=Path("C:/Users/assas/Documents/The-Second-Brain/.worktrees/v2-one-shot")
files=[p/'ledger.sqlite' for p in (h/'state'/'sessions').iterdir() if (p/'ledger.sqlite').is_file()]
r=ledger.internal_session_id("2026-09-05T02-16-14-068Z_01a06f5a-25f4-762b-b74e-1464fa61981f")
def query(p):
 c=sqlite3.connect(p.absolute().as_uri()+'?mode=ro',uri=True,timeout=1)
 try:return c.execute('SELECT internal_session_id,host_session_id FROM sessions WHERE root_parent_session_id=?',(r,)).fetchall()
 finally:c.close()
out={str(n):[] for n in (1,4,8)}
for _ in range(5):
 for n in (1,4,8):
  t=time.perf_counter()
  if n==1: rows=list(map(query,files))
  else:
   with ThreadPoolExecutor(max_workers=n) as p:rows=list(p.map(query,files))
  out[str(n)].append((time.perf_counter()-t)*1000)
print(json.dumps({'samples_ms':out,'medians_ms':{n:statistics.median(v) for n,v in out.items()},'ledger_count':len(files),'result_rows':sum(map(len,rows))},indent=2))
